from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SOURCES = ROOT / 'questions/sources'


def markdown_questions(path):
    text = path.read_text()
    matches = list(re.finditer(r'^### (Q\d+) · (.+)$', text, re.M))
    questions = []
    for i, match in enumerate(matches):
        body = text[match.end():matches[i + 1].start() if i + 1 < len(matches) else text.find('\n## How closely', match.end())]
        body = re.split(r'\n## ', body)[0]
        answer = re.search(r'^\*\*Correct answer: (.+)\*\*\s*$', body, re.M)
        if not answer:
            raise ValueError(f'Missing answer: {match[1]}')
        options_block = body[:answer.start()]
        choices = list(re.finditer(r'^- \*\*([A-Z])\.\*\*\s*(.*)$', options_block, re.M))
        options = [{'id': m[1], 'text': options_block[m.start() + len(f'- **{m[1]}.**'):choices[j + 1].start() if j + 1 < len(choices) else len(options_block)].strip()} for j, m in enumerate(choices)]
        correct = re.findall(r'(?:^|;\s*)([A-Z])\s*—', answer[1])
        if not correct:
            label = answer[1].strip().rstrip('.').lower()
            correct = [o['id'] for o in options if o['text'].lower().rstrip('.') == label]
        if not correct:
            raise ValueError(f'Cannot parse answer: {match[1]} {answer[1]}')
        links = [{'label': a, 'url': b} for a, b in re.findall(r'\[([^\]]+)\]\((https?://[^\s)]+)\)', body[answer.end():])]
        source = next((x['url'] for x in links if 'TF004-PocketGuide/blob/' in x['url']), '')
        chapter = re.search(r'/0([1-8])-', source)
        if not chapter:
            raise ValueError(f'Missing objective source: {match[1]}')
        explanation = re.sub(r'\[Community source[^\n]+', '', body[answer.end():]).strip()
        questions.append({
            'id': 'md-' + match[1].lower(), 'type': {'True/False': 'boolean', 'Multiple Choice': 'single', 'Multiple Answer': 'multiple'}[match[2]],
            'topic': int(chapter[1]), 'prompt': options_block[:choices[0].start()].strip(), 'options': options, 'correct': correct,
            'explanation': explanation, 'references': links,
            'source': {'kind': 'markdown', 'file': path.name, 'number': match[1], 'permission': 'Upstream MIT declaration; attribution retained. Creator permission reported by project owner.'},
            'status': 'ready', 'notes': [],
        })
    return questions


